-- os tres desvios que costumam ser risco DE VERDADE:
-- 1) o banco esta em ARCHIVELOG?
SELECT log_mode, force_logging, flashback_on FROM v$database;

-- 2) grupo de redo com membro unico (perda do membro = perda do grupo):
SELECT group#, COUNT(*) AS membros, MAX(status) AS status
FROM v$logfile GROUP BY group# HAVING COUNT(*) < 2;

-- 3) controlfile multiplexado?
SELECT name FROM v$controlfile;

RMAN> SHOW RETENTION POLICY;
RMAN> SHOW CONTROLFILE AUTOBACKUP;
RMAN> SHOW ALL;

-- redo: seguro e online, um grupo INACTIVE por vez
SELECT group#, status FROM v$log ORDER BY group#;
ALTER DATABASE ADD LOGFILE MEMBER '+DGREDO2' TO GROUP <n>;

-- controlfile: NAO e dinamico. Exige parar, copiar o arquivo e
-- ajustar control_files no spfile antes de subir.
